    await waitFor(() => expect(spy.mock.calls.length).toBeGreaterThan(0));
    const baseline = spy.mock.calls.length;

    // 统一查询重查：活面步节点增删（graph 活面变化随查询一并提交流入）
    loadActiveRun(
      activeRunView({
