    fireEvent.click(screen.getByText('刷新详情'));
    await waitFor(() => expect(screen.getAllByTestId('run-step-node')).toHaveLength(2));

    // 一次刷新周期 = detail 提交 + 产物提交两拍（各一次重算）：挂载随数据源提交
