    expect(screen.queryByTestId('refresh-stale-note')).toBeNull();
  });

  it('图面不塌（AC-1 / D3）：失败轮期间节点集合保持上一成功轮（零 nodes=0 空图）、运行徽章在案；重试轮挂起时 loading 仅作用于「刷新详情」禁用面（无整页加载占位）', async () => {
