/** 发送一轮并等待其落定（发起流由 Record 收口，便于连发两次）。 */
async function sendOnce(
  result: {
    current: { sendMessage: (input: { prompt: string; permissionMode: 'default' }) => void };
  },
  prompt: string,
): Promise<void> {
  act(() => {
    result.current.sendMessage({ prompt, permissionMode: 'default' });
  });
  await act(async () => {});
}

