describe('ChangeCreateDialog：必填与本地 kebab-case 校验（失败留窗零 invoke）', () => {
  beforeEach(() => {
    invokeMock.mockReset();
    invokeMock.mockResolvedValue(OUTCOME);
  });

  it('名称空或 goal 空白（"" / "   "）：点「提交」零 invoke、onCreated 零调用、弹窗不关且行内呈现校验错误', () => {
    const onCreated = vi.fn();
