describe('AgentSessionView：空态与错误面', () => {
  it('sessionId null（自持）→ 空态提示、零取数零订阅', async () => {
    await mountedView({ root: ROOT, sessionId: null });

    expect(screen.getByTestId('agent-session-empty').textContent).toContain('暂无会话');
