    await mountedView({ root: ROOT, sessionId: SESSION_ID });

    await waitFor(() => expect(screen.getByTestId('session-meta')).toBeTruthy());
    expect(screen.queryByTestId('agent-session-failure')).toBeNull();
  });

  it('最新轮停止 → 不展示失败横幅', async () => {
