        apiKey: 'sk-live-1234567890',
        models: TIERS,
        protocol: 'openai',
        contextLength: null,
        maxTokens: null,
        webSearch: false,
      });
    });
    await act(async () => {
      await result.current.remove(1);
    });

    expect(toastErrorMock).not.toHaveBeenCalled();
    expect(result.current.error).toBeNull();
  });
});

