  it('collector 达键数上限后继续产生新键 → 装配层不抛、不重试、driftCount() 恒为 200', async () => {
    for (let index = 0; index < 200; index += 1) {
      const active = Array.from({ length: index + 1 }, (_, position) => ({
        id: `id-${position}`,
        name: `n-${position}`,
        title: `t-${position}`,
        source: 'active',
